const figure = "data:image/png;base64,";
export default function QProbeAnalysisCanvas() {
  const [tab, setTab] = useState("figure");
  const percent = (x) => (100*x).toFixed(2)+"%";
  const num = (x) => x == null ? "未知" : x.toFixed(4);
  const button = (name, label) => <button type="button" onClick={() => setTab(name)} style={{border:"1px solid #d6dfeb",borderRadius:8,padding:"8px 14px",background:tab===name?"#e8f0ff":"white",color:"#183359",cursor:"pointer"}}>{label}</button>;
  return <main style={{fontFamily:"system-ui, -apple-system, BlinkMacSystemFont, sans-serif",maxWidth:1200,margin:"0 auto",padding:24,color:"#172b46",background:"#f7f9fc"}}>
    <header><div style={{fontSize:13,color:"#64748b"}}>Search-G1 qprobe · 换损失前基线 · iteration 1–35</div>
    <h1 style={{fontSize:25,lineHeight:1.35,margin:"8px 0"}}>混合组比例与预测准确率的关系</h1>
    <p style={{maxWidth:900,lineHeight:1.7}}>二分类的跨轮相关由正转负；六分类没有一致的单调下降。中期后，已选题集合内的排序关联转弱。所有曲线使用当轮拟合前预测与已有真实结果。</p>
    <nav aria-label="显示内容" style={{display:"flex",gap:8,marginBottom:16}}>{button("figure","四面板图")}{button("data","逐轮数据")}</nav></header>
    {tab==="figure" ? <figure style={{margin:0,background:"white",borderRadius:12,border:"1px solid #dfe6ef",overflow:"hidden"}}>
      <img src={figure} alt="四面板图：逐轮混合率和二分类六分类准确率，10轮滚动相关，混合识别AUC，预测与真实标准差相关。" style={{display:"block",width:"100%",height:"auto"}}/>
      <figcaption style={{padding:"12px 18px",fontSize:13,lineHeight:1.7,color:"#52647b"}}>B是跨iteration的10轮滚动相关；D是每轮512个题目之间的预测标准差与真实标准差相关，两者口径不同。C和D的深色曲线是后向5轮滑动均值。</figcaption>
    </figure> : <section style={{overflowX:"auto",background:"white",borderRadius:12,border:"1px solid #dfe6ef",padding:12}}>
      <table style={{borderCollapse:"collapse",width:"100%",fontSize:13,textAlign:"right"}}><thead><tr>{["iteration","混合率","二分类准确率","六分类准确率","混合AUC","预测与真实std相关","mixed↔二分类10轮r","mixed↔六分类10轮r"].map(x=><th key={x} style={{padding:"10px 8px",borderBottom:"2px solid #dfe6ef",whiteSpace:"nowrap"}}>{x}</th>)}</tr></thead>
      <tbody>{data.rows.map(x=><tr key={x.iteration}><td style={{padding:8}}>{x.iteration}</td><td>{percent(x.mixed_fraction)}</td><td>{percent(x.binary_accuracy_threshold05)}</td><td>{percent(x.six_accuracy)}</td><td>{num(x.binary_auc_selected)}</td><td>{num(x.sample_correlation_predicted_std_actual_std)}</td><td>{num(data.rolling10.binary_accuracy_threshold05.find(y=>y.last_iteration===x.iteration)?.pearson)}</td><td>{num(data.rolling10.six_accuracy.find(y=>y.last_iteration===x.iteration)?.pearson)}</td></tr>)}</tbody></table>
    </section>}
    <section style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(260px,1fr))",gap:12,marginTop:16}}>
      <article style={{padding:16,background:"white",borderRadius:10,border:"1px solid #dfe6ef"}}><strong>准确率不等于选题命中率</strong><p style={{lineHeight:1.7}}>早期有14轮全部预测为混合，此时二分类准确率等于真实混合率。末5轮二分类准确率58.79%，逐轮多数类基线59.45%。</p></article>
      <article style={{padding:16,background:"white",borderRadius:10,border:"1px solid #dfe6ef"}}><strong>排序信号先升后降</strong><p style={{lineHeight:1.7}}>第11–15轮至第31–35轮，AUC均值从0.598降至0.546；预测与真实std相关均值从0.174降至0.092。全程不是单调下降。</p></article>
    </section>
    <footer style={{fontSize:12,lineHeight:1.8,color:"#64748b",marginTop:16}}>范围：35×512＝17,920个题次，Top512/E0；其余4608个候选没有真实标签。二分类阈值为p1+p2+p3+p4≥0.5；六分类为正确数0–5的argmax。滚动窗口重叠，描述性相关不能证明因果。首5轮与CP5恢复后的逻辑6–35属同一实验链。2026年10月15日记录；未新增采样或评测，当前图作为新sigma3损失的基线。</footer>
  </main>;
}
